[CmdletBinding(SupportsShouldProcess)] param([Parameter(Mandatory)][string]$ProjectPath,[string]$EntryPoint='scripts/run_vm_runtime.py')
if(!(Test-Path (Join-Path $ProjectPath 'pyproject.toml'))){throw 'ProjectPath lacks pyproject.toml'}; if(-not $PSCmdlet.ShouldProcess($ProjectPath,'create guest venv and install extras')){return}; & py -3.12 -m venv (Join-Path $ProjectPath '.venv'); if($LASTEXITCODE){throw 'venv creation failed'}; $python=Join-Path $ProjectPath '.venv\Scripts\python.exe'; & $python -m pip install --upgrade pip; if($LASTEXITCODE){throw 'pip upgrade failed'}; & $python -m pip install "$ProjectPath[web,llm,qq-vm]"; if($LASTEXITCODE){throw 'dependency install failed'}; Write-Output "Installed; configure DPAPI vault then start manually: $EntryPoint"
